  layout: Layout;
  cols: number;
  rowHeight: number;
  gap?: number;
  editable?: boolean;
  onLayoutChange: (layout: Layout) => void;
  renderItem: (api: ItemRenderApi) => ReactNode;
  className?: string;
}

