            <div
              key={item.id}
              className={[
                'grid-layout__item',
                isDragging && 'grid-layout__item_dragging',
                isDragging && drag?.kind === 'resize' && 'grid-layout__item_resizing',
              ]
                .filter(Boolean)
                .join(' ')}
              style={{
                transform: `translate(${px.left}px, ${px.top}px)`,
                width: px.width,
                height: px.height,
              }}
              data-grid-id={item.id}
