                        style={{ fill: `var(--viz-series-${s.slot})`, pointerEvents: 'none' }}
                      />
                    ))}
                  </g>
                )}
              </svg>
            )}
            {hover != null && (
              <ChartTooltip
                x={x(hover)}
                y={M.top}
                width={width}
                title={formatDate(traffic[hover].date, 'long')}
                rows={TRAFFIC_SERIES.map((s) => ({
                  name: s.name,
                  value: formatNumber(traffic[hover].values[s.id]),
                  color: `var(--viz-series-${s.slot})`,
                }))}
              />
